INSERT INTO request_types (
    code, subcategory_id, name, description, ticket_type, responsible_area_id,
    minimum_priority, base_risk, allows_anonymous, requires_location, active,
    affected_population_factor
)
SELECT
    seed.code, s.id, seed.name, seed.description, seed.ticket_type, seed.responsible_area_id,
    'LOW', 'LOW', FALSE, FALSE, TRUE, 0.0000::numeric
FROM seed
         JOIN categories c ON c.name = seed.category_name
         JOIN subcategories s ON s.category_id = c.id AND s.name = seed.subcategory_name
    ON CONFLICT (code) DO UPDATE SET
    subcategory_id = EXCLUDED.subcategory_id,
                              name = EXCLUDED.name,
                              description = EXCLUDED.description,
                              ticket_type = EXCLUDED.ticket_type,
                              responsible_area_id = EXCLUDED.responsible_area_id,
                              minimum_priority = EXCLUDED.minimum_priority,
                              base_risk = EXCLUDED.base_risk,
                              allows_anonymous = EXCLUDED.allows_anonymous,
                              requires_location = EXCLUDED.requires_location,
                              active = EXCLUDED.active,
                              affected_population_factor = EXCLUDED.affected_population_factor;

