INSERT INTO form_fields (
    form_template_id, code, label, type, required, display_order, config
)
SELECT
    ft.id, seed.field_code, seed.label, seed.field_type, seed.required,
    seed.display_order, seed.config::jsonb
FROM seed
         JOIN request_types rt ON rt.code = seed.request_type_code
         JOIN form_templates ft ON ft.request_type_id = rt.id AND ft.version = 1
    ON CONFLICT (form_template_id, code) DO UPDATE SET
    label = EXCLUDED.label,
                                                type = EXCLUDED.type,
                                                required = EXCLUDED.required,
                                                display_order = EXCLUDED.display_order,
                                                config = EXCLUDED.config;

